args.sql:
SELECT ab.a_type, COUNT(*) FROM assessmentbasics ab 
JOIN assessmentsocialanddiagnosis asd ON ab.ab_key = asd.asd_key 
GROUP BY ab.a_type ORDER BY COUNT(*) DESC;

